import React from "react";
import {Link} from "react-router-dom";
function Navigation(){
    return(
        <>
        <Link to="/">Home</Link>
        <Link to="/aboutus">About Us</Link>
        <Link to="/contactus">Contact Us</Link>
        </>
    );
}
